// The model's fill-up form (Model/Logbook.orm's RecordFillUp, generated by
// ormtool xforms) run as the desktop app runs it, XFormsKit answered by
// LBFormHost: against a store of the model's own (a SQLite file, saved as
// the server saves), and against a server's OData service. Each check a
// line, "ok" or "FAIL"; 1 when one failed.
//
//   lb-form-check build/Logbook.momd build/Logbook.ormplans build/Model/Forms [http://127.0.0.1:8080/odata/]
//
// - opened for a vehicle, by its owner: the vehicle and who enters it
//   given, the driver's choices its
//   owner and those it is shared with, no one else;
// - filled in and saved: the fill-up there, its compounds (mileage, volume,
//   cost) whole, the tank filled;
// - a driver who does not drive the vehicle refused, said at the driver
//   or of the form, nothing saved;
// - the server: the same over OData (a POST), read back by its key, changed
//   (a PATCH of what changed, If-Match its version) and read again.
#import <Foundation/Foundation.h>
#import <CoreData/CoreData.h>
#import <XFormsKit/XFormsKit.h>
#import <ORMRuntime/ORMForm.h>
#import <ORMRuntime/ORMTables.h>
#import "LogbookValidation.h"
#import "LBFormHost.h"
#import "Vehicle+CoreDataClass.h"
#import "User+CoreDataClass.h"
#import "FillUp+CoreDataClass.h"
#import "VehicleDriver+CoreDataClass.h"
#import "DistanceUnit+CoreDataClass.h"
#import "VolumeUnit+CoreDataClass.h"

static NSUInteger LBFailures;
static NSManagedObjectModel *LBModel;
static ORMForm *LBForm;
static NSString *LBDocument;

static void LBCheck(NSString *what, BOOL ok, id detail) {
    printf("%s %s%s\n", ok ? "ok  " : "FAIL", what.UTF8String,
           ok || !detail ? "" : [[NSString stringWithFormat:@": %@", detail] UTF8String]);
    fflush(stdout);
    if (!ok) LBFailures++;
}

static id LBInsert(Class cls, NSManagedObjectContext *context) {
    return [NSEntityDescription insertNewObjectForEntityForName:NSStringFromClass(cls) inManagedObjectContext:context];
}

static id LBFetchKey(Class cls, NSString *key, id value, NSManagedObjectContext *context) {
    NSFetchRequest *fetch = [NSFetchRequest fetchRequestWithEntityName:NSStringFromClass(cls)];
    fetch.predicate = [NSPredicate predicateWithFormat:@"%K == %@", key, value];
    return [[context executeFetchRequest:fetch error:NULL] firstObject];
}

/* A context over a new SQLite store, its reference data seeded. */
static NSManagedObjectContext *LBNewStore(void) {
    NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:
                                                 [NSString stringWithFormat:@"lb-form-%@.sqlite", [NSProcessInfo processInfo].globallyUniqueString]];
    NSPersistentStoreCoordinator *coordinator = [[NSPersistentStoreCoordinator alloc] initWithManagedObjectModel:LBModel];
    NSError *error = nil;
    if (![coordinator addPersistentStoreWithType:NSSQLiteStoreType configuration:nil URL:[NSURL fileURLWithPath:path] options:nil
                                           error:&error]) {
        printf("FAIL the store at %s: %s\n", path.UTF8String, error.localizedDescription.UTF8String);
        exit(1);
    }
    NSManagedObjectContext *context = [[NSManagedObjectContext alloc] initWithConcurrencyType:NSMainQueueConcurrencyType];
    context.persistentStoreCoordinator = coordinator;
    if (![LogbookReferenceData seedContext:context error:&error] || ![context save:&error]) {
        printf("FAIL seeded: %s\n", error.localizedDescription.UTF8String);
        exit(1);
    }
    return context;
}

/* A user of the email, and a vehicle of the owner. */
static User *LBUser(NSString *email, NSManagedObjectContext *context) {
    User *user = LBInsert([User class], context);
    user.email = email;
    return user;
}

static Vehicle *LBVehicle(NSString *name, User *owner, NSManagedObjectContext *context) {
    Vehicle *vehicle = LBInsert([Vehicle class], context);
    vehicle.id = [NSUUID UUID];
    vehicle.vehicleName = name;
    vehicle.make = @"Volkswagen";
    vehicle.carModel = name;
    vehicle.manufactureYear = 2016;
    vehicle.fuel = @"Petrol";
    vehicle.owner = owner;
    return vehicle;
}

/* The control the element is entered with, among the controls and in
   their groups (a compound's parts). */
static XFControl *LBFieldIn(NSArray<XFControl *> *controls, NSString *element) {
    for (XFControl *control in controls) {
        if ([control isKindOfClass:[XFGroup class]]) {
            XFControl *found = LBFieldIn(((XFGroup *)control).children, element);
            if (found) return found;
        } else if ([control.boundNode.localName isEqualToString:element]) {
            return control;
        }
    }
    return nil;
}

static XFControl *LBField(XFProcessor *processor, NSString *element) {
    return LBFieldIn(processor.controls, element);
}

/* Typed into the form, as its view does. */
static void LBEnter(XFProcessor *processor, NSDictionary<NSString *, NSString *> *values) {
    [values enumerateKeysAndObjectsUsingBlock:^(NSString *element, NSString *value, BOOL *stop) {
        XFControl *control = LBField(processor, element);
        NSError *error = nil;
        if (!control || ![processor setValue:value ofControl:control error:&error]) {
            LBCheck([NSString stringWithFormat:@"%@ entered", element], NO, error ?: @"no control");
        }
    }];
}

static void LBSaidOf(NSArray<XFControl *> *controls) {
    for (XFControl *control in controls) {
        if ([control isKindOfClass:[XFGroup class]]) LBSaidOf(((XFGroup *)control).children);
        else if (!control.valid || (control.required && !control.stringValue.length))
            printf("  %s: valid %d required %d value '%s' alert %s\n", control.boundNode.localName.UTF8String, control.valid, control.required,
                   control.stringValue.UTF8String, control.alert.UTF8String ?: "");
    }
}

static void LBSubmit(XFProcessor *processor) {
    [[processor.model submissionWithIdentifier:@"save"] submit];
    if (getenv("LB_FORM_DEBUG")) LBSaidOf(processor.controls);
}

/* The choices the form was given for the reference. */
static NSArray<NSString *> *LBChoices(XFProcessor *processor, NSString *name) {
    XFXMLElement *root = [[processor.model instanceWithIdentifier:[@"choices-" stringByAppendingString:name]] documentElement];
    NSMutableArray *keys = [NSMutableArray array];
    for (XFXMLNode *item in root.children) {
        if (item.kind == XFXMLElementKind) [keys addObject:item.stringValue ?: @""];
    }
    return keys;
}

static NSDictionary<NSString *, NSString *> *LBFillUp(NSString *driver) {
    return @{
        @"timestamp" : @"2026-11-10T08:30:00Z",
        @"mileageQuantity" : @"12345",
        @"mileageDistanceUnit" : @"km",
        @"volumeQuantity" : @"40.5",
        @"volumeVolumeUnit" : @"L",
        @"fuel" : @"Petrol 95",
        @"station" : @"Shell",
        @"totalAmount" : @"60.75",
        @"totalCurrency" : @"EUR",
        @"driver" : driver,
        @"filledTheTank" : @"true",
    };
}

#pragma mark A store of its own

static void LBStoreSteps(void) {
    NSManagedObjectContext *context = LBNewStore();
    User *anna = LBUser(@"anna@example.org", context), *ben = LBUser(@"ben@example.org", context);
    User *carl = LBUser(@"carl@example.org", context);
    Vehicle *golf = LBVehicle(@"Golf", anna, context);
    LBVehicle(@"Polo", carl, context);
    VehicleDriver *sharing = LBInsert([VehicleDriver class], context);
    sharing.id = [NSUUID UUID];
    sharing.vehicle = golf;
    sharing.user = ben;
    NSError *error = nil;
    if (![context orm_prepareForSave:&error] || ![context save:&error]) {
        LBCheck(@"the people and their cars saved", NO, error);
        return;
    }
    BOOL (^saving)(NSManagedObjectContext *, NSError **) = ^BOOL(NSManagedObjectContext *c, NSError **failure) {
        return [c orm_prepareForSave:failure] && [c save:failure];
    };
    LBFormHost *host = [[LBFormHost alloc] initWithForm:LBForm document:LBDocument given:@{ @"vehicle" : golf.id.UUIDString, @"enteredBy" : anna.email }];
    [host useContext:context saving:saving];
    XFProcessor *processor = [host makeProcessor:&error];
    LBCheck(@"the form runs", processor != nil, error);
    if (!processor) return;
    LBCheck(@"opened for the Golf", [host.instance[@"vehicle"] isEqualToString:golf.id.UUIDString], host.instance);
    NSArray *drivers = LBChoices(processor, @"driver");
    LBCheck(@"its drivers: Anna, who owns it, and Ben, whom it is shared with; not Carl",
            [drivers containsObject:@"anna@example.org"] && [drivers containsObject:@"ben@example.org"]
                && ![drivers containsObject:@"carl@example.org"],
            drivers);
    LBEnter(processor, LBFillUp(@"ben@example.org"));
    LBCheck(@"the price per unit worked out in the form", [host.instance[@"pricePerUnit"] doubleValue] == 1.5, host.instance[@"pricePerUnit"]);
    LBSubmit(processor);
    FillUp *saved = host.savedKey ? LBFetchKey([FillUp class], @"id", [[NSUUID alloc] initWithUUIDString:host.savedKey], context) : nil;
    LBCheck(@"saved", saved != nil, host.formMessages);
    LBCheck(@"the fill-up as entered: the Golf's, Ben's, whole",
            saved.vehicle == golf && saved.driver == ben && saved.mileageQuantity.integerValue == 12345
                && [saved.mileageDistanceUnit.code isEqualToString:@"km"] && [saved.volumeQuantity.stringValue isEqualToString:@"40.5"]
                && [saved.volumeVolumeUnit.code isEqualToString:@"L"] && [saved.totalAmount.stringValue isEqualToString:@"60.75"]
                && [saved.totalCurrency isEqualToString:@"EUR"] && [saved.station isEqualToString:@"Shell"] && saved.filledTheTank,
            [NSString stringWithFormat:@"%@ %@ %@ %@ %@", saved.driver.email, saved.mileageQuantity, saved.volumeQuantity,
                                       saved.totalAmount, saved.totalCurrency]);
    LBCheck(@"the form has its key now", [host.instance[@"id"] isEqualToString:host.savedKey ?: @"-"], host.instance[@"id"]);

    /* Carl does not drive the Golf: the store's rule refuses it. */
    LBFormHost *refused = [[LBFormHost alloc] initWithForm:LBForm document:LBDocument given:@{ @"vehicle" : golf.id.UUIDString, @"enteredBy" : anna.email }];
    [refused useContext:context saving:saving];
    processor = [refused makeProcessor:&error];
    NSMutableDictionary *carls = [LBFillUp(@"carl@example.org") mutableCopy];
    carls[@"timestamp"] = @"2026-11-10T09:30:00Z";
    LBEnter(processor, carls);
    NSUInteger before = [context countForFetchRequest:[NSFetchRequest fetchRequestWithEntityName:@"FillUp"] error:NULL];
    LBSubmit(processor);
    NSString *atDriver = LBField(processor, @"driver").hostError;
    LBCheck(@"a driver who does not drive the Golf refused, said at the driver or of the form",
            !refused.savedKey && (atDriver.length || refused.formMessages.count), refused.formMessages);
    LBCheck(@"nothing saved", [context countForFetchRequest:[NSFetchRequest fetchRequestWithEntityName:@"FillUp"] error:NULL] == before
                                  && !context.hasChanges, nil);
    printf("said: %s\n", (atDriver ?: [refused.formMessages componentsJoinedByString:@"; "]).UTF8String);
    LBEnter(processor, @{ @"driver" : @"anna@example.org" });
    LBCheck(@"what was said at the driver gone once it is changed", LBField(processor, @"driver").hostError == nil,
            LBField(processor, @"driver").hostError);
    LBSubmit(processor);
    LBCheck(@"and saved with Anna", refused.savedKey != nil, refused.formMessages);
}

#pragma mark The server

/* POSTed as JSON: what the server makes of it. */
static NSDictionary *LBPost(NSURL *root, NSString *set, NSDictionary *body) {
    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:set relativeToURL:root]];
    request.HTTPMethod = @"POST";
    request.HTTPBody = [NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
    [request setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
    __block NSData *data = nil;
    __block NSInteger status = 0;
    __block BOOL done = NO;
    [[[NSURLSession sharedSession] dataTaskWithRequest:request completionHandler:^(NSData *d, NSURLResponse *r, NSError *e) {
        data = d;
        status = [(NSHTTPURLResponse *)r statusCode];
        done = YES;
    }] resume];
    while (!done) [[NSRunLoop currentRunLoop] runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.02]];
    if (status >= 300) {
        LBCheck([NSString stringWithFormat:@"%@ made on the server", set], NO,
                [[NSString alloc] initWithData:data ?: [NSData data] encoding:NSUTF8StringEncoding]);
        return nil;
    }
    return [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
}

static void LBServiceSteps(NSURL *root) {
    /* A vehicle of Anna's, and Ben its other driver. */
    NSString *golf = [NSUUID UUID].UUIDString;
    LBPost(root, @"Users", @{ @"Email" : @"anna@example.org" });
    LBPost(root, @"Users", @{ @"Email" : @"ben@example.org" });
    if (!LBPost(root, @"Vehicles", @{ @"Id" : golf, @"VehicleName" : @"Golf", @"Make" : @"Volkswagen", @"CarModel" : @"Golf",
                                      @"ManufactureYear" : @2016, @"Fuel" : @"Petrol",
                                      @"Owner@odata.bind" : @"Users('anna@example.org')" })) return;
    LBPost(root, @"VehicleDrivers", @{ @"Vehicle@odata.bind" : [NSString stringWithFormat:@"Vehicles(%@)", golf],
                                       @"User@odata.bind" : @"Users('ben@example.org')" });
    LBFormHost *host = [[LBFormHost alloc] initWithForm:LBForm document:LBDocument given:@{ @"vehicle" : golf, @"enteredBy" : @"anna@example.org" }];
    [host useServiceRoot:root model:LBModel signIn:nil];
    NSError *error = nil;
    XFProcessor *processor = [host makeProcessor:&error];
    LBCheck(@"the form runs against the server", processor != nil, error);
    if (!processor) return;
    NSArray *drivers = LBChoices(processor, @"driver");
    LBCheck(@"the server's drivers of the Golf: Anna and Ben",
            [drivers containsObject:@"anna@example.org"] && [drivers containsObject:@"ben@example.org"], drivers);
    LBEnter(processor, LBFillUp(@"anna@example.org"));
    LBSubmit(processor);
    NSString *key = host.savedKey;
    LBCheck(@"sent to the server (POST), its key the server's", key.length > 0, host.formMessages);
    if (!key.length) return;

    /* Opened again for it: read from the server, changed, sent (PATCH). */
    LBFormHost *again = [[LBFormHost alloc] initWithForm:LBForm document:LBDocument given:@{}];
    [again useServiceRoot:root model:LBModel signIn:nil];
    again.key = key;
    processor = [again makeProcessor:&error];
    NSDictionary *read = again.instance;
    LBCheck(@"read back from the server as it was sent",
            [read[@"vehicle"] caseInsensitiveCompare:golf] == NSOrderedSame && [read[@"station"] isEqualToString:@"Shell"]
                && [read[@"driver"] isEqualToString:@"anna@example.org"] && [read[@"mileageQuantity"] doubleValue] == 12345
                && [read[@"mileageDistanceUnit"] isEqualToString:@"km"] && [read[@"filledTheTank"] isEqualToString:@"true"],
            read);
    LBEnter(processor, @{ @"station" : @"Aral", @"driver" : @"ben@example.org" });
    LBSubmit(processor);
    LBCheck(@"changed on the server (PATCH)", again.savedKey != nil, again.formMessages);
    LBCheck(@"and read again as changed", [again.instance[@"station"] isEqualToString:@"Aral"]
                                              && [again.instance[@"driver"] isEqualToString:@"ben@example.org"],
            again.instance);
}

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        if (argc < 4) {
            fprintf(stderr, "usage: lb-form-check Logbook.momd Logbook.ormplans Forms/ [service root]\n");
            return 2;
        }
        LBModel = [[NSManagedObjectModel alloc] initWithContentsOfURL:[NSURL fileURLWithPath:@(argv[1])]];
        NSError *error = nil;
        NSData *plans = [NSData dataWithContentsOfFile:@(argv[2])];
        id list = plans ? [NSPropertyListSerialization propertyListWithData:plans options:0 format:NULL error:&error] : nil;
        ORMTables *tables = list ? [ORMTables tablesWithPropertyList:list error:&error] : nil;
        NSString *forms = @(argv[3]);
        NSData *table = [NSData dataWithContentsOfFile:[forms stringByAppendingPathComponent:@"RecordFillUp.ormform"]];
        id formList = table ? [NSPropertyListSerialization propertyListWithData:table options:0 format:NULL error:&error] : nil;
        LBForm = formList ? [ORMForm formWithPropertyList:formList error:&error] : nil;
        LBDocument = [NSString stringWithContentsOfFile:[forms stringByAppendingPathComponent:@"RecordFillUp.xhtml"]
                                               encoding:NSUTF8StringEncoding error:NULL];
        if (!LBModel.entities.count || !tables || !LBForm || !LBDocument) {
            fprintf(stderr, "no model at %s, tables at %s, or form in %s: %s\n", argv[1], argv[2], argv[3],
                    error.localizedDescription.UTF8String ?: "");
            return 2;
        }
        [ORMTables registerTables:tables named:@"Logbook"];
        LBStoreSteps();
        if (argc > 4) LBServiceSteps([NSURL URLWithString:@(argv[4])]);
        printf("form: %lu failed\n", (unsigned long)LBFailures);
    }
    return LBFailures ? 1 : 0;
}
